// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address sender, address target, bool emergency, uint256 amount) public {
        // Bound amount to avoid extreme values (optional)
        amount = bound(amount, 0, 1e30);

        // Record DAO before call
        address daoBefore = address(this); // DAO is set to address(this) in constructor

        // Drive through public surface: we need to call assertGovernanceApproved,
        // but it requires msg.sender == DAO || governed[msg.sender].
        // We set msg.sender to DAO (address(this)).
        vm.prank(address(this));

        // Attempt the call - it may revert due to many reasons, but we care about state after any revert.
        // We wrap in try/catch to handle reverts.
        try c.assertGovernanceApproved(sender, target, emergency) {
            // Success: check DAO unchanged
            address daoAfter = c.DAO();
            assertTrue(daoAfter == daoBefore, "DAO changed after successful call");
        } catch {
            // Revert: check DAO unchanged
            address daoAfter = c.DAO();
            assertTrue(daoAfter == daoBefore, "DAO changed after reverted call");
        }
    }
}

